import 'package:cbl/cbl.dart';

Future<void> run() async {
  final db = await Database.openAsync('mydb');
  final coll = await db.createCollection('items');
  final doc = MutableDocument({'name':'example'});
  await coll.saveDocument(doc);
  final fetched = await coll.document(doc.id);
  print('Fetched: ${fetched?.string('name')}');
  await db.close();
}
